-- ============================================================================
-- BABY DQ FLAGS - per baby counts and the list of missing mandatory / conditional fields
-- INPUT: a table or CTE named `mahis_pivot` (output of the MAHIS pivot query, joined with
-- patient columns gender, birthdate, ... ). To use a CTE instead of a table, put this script's
-- WITH list after `WITH RECURSIVE mahis_pivot AS ( <pivot query> ),`
-- Generated by build_dqa_scripts.py from the MNH Neonatal data dictionary rules.
-- ============================================================================
SET SESSION group_concat_max_len = 1000000;

WITH baby_level AS (
    -- One row per baby: latest non-empty value of each field across all visit days
    SELECT
        p.person_id,
        SUBSTRING_INDEX(GROUP_CONCAT(p.location_id ORDER BY p.visit_date DESC), ',', 1) AS location_id,
        MIN(p.visit_date) AS first_visit_date,
        MAX(p.visit_date) AS last_visit_date,
        COUNT(DISTINCT p.visit_date) AS number_of_visits,
        DATEDIFF(MAX(p.visit_date), MIN(p.visit_date)) + 1 AS days_spanned,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdominal_distension AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdominal_distension,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.palate AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS palate,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.head AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS head,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.blood_sugar AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS blood_sugar,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.teo AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS teo,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.skin_rash AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS skin_rash,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.splenomegaly AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS splenomegaly,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mode_of_transport AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mode_of_transport,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.treatment AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS treatment,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.activity AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS activity,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.drug_end_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS drug_end_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.colour AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS colour,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.lab_order_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS lab_order_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.capillary_refill_time AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS capillary_refill_time,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.color_of_urine AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS color_of_urine,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.vitamin_k_given AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS vitamin_k_given,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mode_of_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mode_of_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.current_weight AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS current_weight,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_breathing_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_breathing_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.oxygen_saturation_on_oxygen AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS oxygen_saturation_on_oxygen,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.can_measure_oxygen_saturation AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS can_measure_oxygen_saturation,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.oxygen_available_at_facility AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS oxygen_available_at_facility,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.can_measure_temperature AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS can_measure_temperature,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.blood_sugar_unit AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS blood_sugar_unit,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.referral_facility AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS referral_facility,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.musculoskeletal_deformities AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS musculoskeletal_deformities,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.oxygen_saturation AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS oxygen_saturation,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.normal_heart_sounds AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS normal_heart_sounds,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.offensive_liquor AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS offensive_liquor,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.gestation_in_weeks AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS gestation_in_weeks,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_given_nvp AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_given_nvp,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_tested_hepatitis AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_tested_hepatitis,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.birth_asphyxia_suspected AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS birth_asphyxia_suspected,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.do_hiv_retest AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS do_hiv_retest,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.is_baby_vomiting AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS is_baby_vomiting,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_passing_urine AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_passing_urine,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mother_treated_vdrl AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mother_treated_vdrl,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.stethoscope_available AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS stethoscope_available,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdomen_color_change AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdomen_color_change,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdomen_distended_veins AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdomen_distended_veins,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdomen_shiny AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdomen_shiny,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdomen_soft_normal AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdomen_soft_normal,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.abdomen_tender AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS abdomen_tender,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.blood_in_stools AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS blood_in_stools,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.chest_clear AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS chest_clear,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.spinal_bifida AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS spinal_bifida,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.chlorohexidine_cord_care AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS chlorohexidine_cord_care,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mother_name AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mother_name,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.birth_facility_name AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS birth_facility_name,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.referring_facility_name AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS referring_facility_name,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.skin_findings AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS skin_findings,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.palpable_kidneys AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS palpable_kidneys,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mucus_in_stools AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mucus_in_stools,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.color_of_stools AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS color_of_stools,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.consistency_of_stools AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS consistency_of_stools,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.passage_of_meconium AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS passage_of_meconium,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.extra_digits AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS extra_digits,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.talipes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS talipes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.duration_of_feeding AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS duration_of_feeding,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.effort_during_feeding AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS effort_during_feeding,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.frequency_of_feeding AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS frequency_of_feeding,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.suck_reflex AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS suck_reflex,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.grasp_reflex AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS grasp_reflex,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.moro_reflex AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS moro_reflex,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.tone_assessment AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS tone_assessment,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.thompson_consciousness_score AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS thompson_consciousness_score,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.thompson_fits_score AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS thompson_fits_score,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.thompson_fontanelle_score AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS thompson_fontanelle_score,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.thompson_grasp_score AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS thompson_grasp_score,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.thompson_moro_score AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS thompson_moro_score,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.thompson_posture_score AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS thompson_posture_score,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.thompson_respiration_score AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS thompson_respiration_score,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.thompson_suck_score AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS thompson_suck_score,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.thompson_tone_score AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS thompson_tone_score,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.thermal_care AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS thermal_care,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.admitted_from AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS admitted_from,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mother_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mother_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.multiple_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS multiple_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.type_of_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS type_of_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.cried_after_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS cried_after_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.resuscitation_method AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS resuscitation_method,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.gestation_method_assessment AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS gestation_method_assessment,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.ultrasound_scanning AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS ultrasound_scanning,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.onset_of_labor AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS onset_of_labor,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.rupture_of_membranes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS rupture_of_membranes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.meconium_present AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS meconium_present,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.maternal_analgesia AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS maternal_analgesia,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anesthesia_used AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anesthesia_used,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.last_hiv_test_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS last_hiv_test_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mother_vdrl_result AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mother_vdrl_result,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.three_doses_completed AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS three_doses_completed,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mother_hepatitis_result AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mother_hepatitis_result,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.fontanelle AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS fontanelle,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.femoral_pulses AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS femoral_pulses,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.anus_assessment AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS anus_assessment,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.genitalia AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS genitalia,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.congenital_abnormality AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS congenital_abnormality,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.comment_to_fulfiller AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS comment_to_fulfiller,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.workstation_location AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS workstation_location,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.reason_for_test AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS reason_for_test,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.clinician_notes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS clinician_notes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.place_of_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS place_of_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.hepatomegaly AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS hepatomegaly,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.pulse AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS pulse,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.temperature AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS temperature,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.weight AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS weight,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.respiratory_rate AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS respiratory_rate,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.head_circumference AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS head_circumference,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.birth_weight AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS birth_weight,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.person_making_request AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS person_making_request,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.referred AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS referred,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.primary_diagnosis AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS primary_diagnosis,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.secondary_diagnosis AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS secondary_diagnosis,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.tetanus_diphtheria AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS tetanus_diphtheria,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.nasal_flaring AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS nasal_flaring,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.central_cyanosis AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS central_cyanosis,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.referred_from AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS referred_from,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.respiratory_distress AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS respiratory_distress,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mother_hiv_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mother_hiv_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.presenting_complaint AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS presenting_complaint,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.avpu AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS avpu,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.test_type AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS test_type,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.hiv_unknown AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS hiv_unknown,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.readmission AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS readmission,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.hiv_low_risk AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS hiv_low_risk,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.type_of_feed AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS type_of_feed,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mode_of_feeding AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mode_of_feeding,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.weight_trend_since_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS weight_trend_since_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_oral_thrush AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_oral_thrush,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_oral_sores AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_oral_sores,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_tongue_tie AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_tongue_tie,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.umbilical_condition AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS umbilical_condition,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.umbilicus_healthy AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS umbilicus_healthy,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.mother_identifier AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS mother_identifier,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.known_medical_condition AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS known_medical_condition,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.clinical_review_outcome AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS clinical_review_outcome,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_catheterized AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_catheterized,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_feeding AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_feeding,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.duration_rupture_membranes AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS duration_rupture_membranes,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.analgesia_drug AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS analgesia_drug,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.lab_test_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS lab_test_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.tactile_trunk_temperature AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS tactile_trunk_temperature,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.airway_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS airway_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.warm_peripherals AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS warm_peripherals,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.pulse_volume AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS pulse_volume,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.convulsions_or_twitching AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS convulsions_or_twitching,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.signs_of_dehydration AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS signs_of_dehydration,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.breathing_triage AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS breathing_triage,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_dehydrated AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_dehydrated,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.oxygen_unavailable_reason AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS oxygen_unavailable_reason,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.fast_breathing AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS fast_breathing,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.apgar_score_1_min AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS apgar_score_1_min,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.apgar_score_5_min AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS apgar_score_5_min,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.protected_at_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS protected_at_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.tdv_doses_received AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS tdv_doses_received,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_crying AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_crying,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.apgar_score_10_min AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS apgar_score_10_min,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.oxygen_therapy AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS oxygen_therapy,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.feeding_support AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS feeding_support,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.multiple_birth_type AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS multiple_birth_type,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.steroids_given AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS steroids_given,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.hiv_status AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS hiv_status,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.severe_respiratory_distress AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS severe_respiratory_distress,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.weight_grams AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS weight_grams,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.crt_3_or_more_seconds AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS crt_3_or_more_seconds,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.central_capillary_refill_time AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS central_capillary_refill_time,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.baby_symptomatic_low_blood_sugar AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS baby_symptomatic_low_blood_sugar,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.femoral_pulse_palpable AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS femoral_pulse_palpable,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.crt_less_than_3_seconds AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS crt_less_than_3_seconds,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.triage_priority AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS triage_priority,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.frequency_of_stooling AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS frequency_of_stooling,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.wet_nappies_per_day AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS wet_nappies_per_day,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.time_of_delivery AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS time_of_delivery,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.height_cm AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS height_cm,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.circumference_cm AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS circumference_cm,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.cried_at_birth AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS cried_at_birth,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.newborn_complications AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS newborn_complications,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.gender AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS gender,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.birthdate AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS birthdate,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.birthdate_estimated AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS birthdate_estimated,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.first_mahis_visit AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS first_mahis_visit,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.age_days_at_first_mahis_visit AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS age_days_at_first_mahis_visit,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.dead AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS dead,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.death_date AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS death_date,
        SUBSTRING_INDEX(GROUP_CONCAT(NULLIF(TRIM(CAST(p.cause_of_death AS CHAR)), '') ORDER BY p.visit_date DESC SEPARATOR '|~|'), '|~|', 1) AS cause_of_death
    FROM mahis_pivot p
    GROUP BY p.person_id
),

rules AS (
    SELECT 'mother_identifier' AS rule_id, 'nn_demog_selected_mother' AS dictionary_name, 'Search and select mother' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'multiple_birth_type' AS rule_id, 'nn_birth_twin' AS dictionary_name, 'Does the baby have a twin?' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'place_of_birth' AS rule_id, 'nn_birth_place_birth' AS dictionary_name, 'Place of birth' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'multiple_birth' AS rule_id, 'nn_birth_type_birth' AS dictionary_name, 'Type of birth' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'birthdate' AS rule_id, 'nn_birth_birth_date' AS dictionary_name, 'Date of birth' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'type_of_birth' AS rule_id, 'nn_birth_birth_time' AS dictionary_name, 'Time of birth' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, 'pivot: Time of birth / Time of delivery' AS condition_text
    UNION ALL
    SELECT 'referred' AS rule_id, 'nn_ref_in_referred_from_another_facility' AS dictionary_name, 'Is the baby referred from another facility?' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'cried_after_birth' AS rule_id, 'nn_birth_assess_cried_after_birth' AS dictionary_name, 'Did the baby cry straight after birth?' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'gestation_in_weeks' AS rule_id, 'nn_preg_hist_gestation_weeks' AS dictionary_name, 'Gestation in weeks' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'gestation_method_assessment' AS rule_id, 'nn_preg_hist_gestation_method_assessment' AS dictionary_name, 'Gestation method assessment' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'onset_of_labor' AS rule_id, 'nn_preg_hist_onset_labor_date' AS dictionary_name, 'Onset of labor date/time' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'rupture_of_membranes' AS rule_id, 'nn_preg_hist_rupture_membranes' AS dictionary_name, 'Rupture of membranes?' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'offensive_liquor' AS rule_id, 'nn_preg_hist_offensive_liquor' AS dictionary_name, 'Offensive liquor?' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'mode_of_delivery' AS rule_id, 'nn_preg_hist_mode_delivery' AS dictionary_name, 'Mode of delivery' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'meconium_present' AS rule_id, 'nn_preg_hist_meconium_present' AS dictionary_name, 'Meconium present?' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'maternal_analgesia' AS rule_id, 'nn_preg_hist_maternal_analgesia' AS dictionary_name, 'Maternal analgesia?' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'anesthesia_used' AS rule_id, 'nn_preg_hist_anesthesia_used' AS dictionary_name, 'Anesthesia used?' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'teo' AS rule_id, 'nn_preg_hist_teo' AS dictionary_name, 'TEO?' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'chlorohexidine_cord_care' AS rule_id, 'nn_preg_hist_chlorohexidine_cord_care' AS dictionary_name, 'Chlorohexidine of cord care?' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'vitamin_k_given' AS rule_id, 'nn_preg_hist_vitamin_kgiven' AS dictionary_name, 'Vitamin K given?' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'mother_status' AS rule_id, 'nn_mother_mother_status' AS dictionary_name, 'Mother''s status' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'mother_hiv_status' AS rule_id, 'nn_mother_mother_hiv_status' AS dictionary_name, 'Mother HIV status' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, 'pivot: Mother HIV Status / HIV status' AS condition_text
    UNION ALL
    SELECT 'last_hiv_test_date' AS rule_id, 'nn_mother_last_hiv_test_date' AS dictionary_name, 'Last HIV test date' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'mother_vdrl_result' AS rule_id, 'nn_mother_mother_vdrl_result' AS dictionary_name, 'Mother''s VDRL/Syphilis result' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'baby_tested_hepatitis' AS rule_id, 'nn_mother_baby_tested_hepatitis' AS dictionary_name, 'Was the baby tested for Hepatitis?' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'known_medical_condition' AS rule_id, 'nn_med_cond_known_medical_conditions' AS dictionary_name, 'Mother''s known medical conditions' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'tetanus_diphtheria' AS rule_id, 'nn_med_cond_tetanus_diphtheria' AS dictionary_name, 'Tetanus Diphtheria' AS label, 'Enrollment' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'birth_facility_name' AS rule_id, 'nn_birth_birth_facility' AS dictionary_name, 'Name of birth facility' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Place of birth = Hospital/Health Center and baby not born at this facility (proxy: referred = Yes)' AS condition_text
    UNION ALL
    SELECT 'referred_from' AS rule_id, 'nn_ref_in_referred_from' AS dictionary_name, 'Referred from' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Referred from another facility = Yes' AS condition_text
    UNION ALL
    SELECT 'referring_facility_name' AS rule_id, 'nn_ref_in_referring_facility_name' AS dictionary_name, 'Name of referring facility' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Referred = Yes and Referred from <> Other' AS condition_text
    UNION ALL
    SELECT 'mode_of_transport' AS rule_id, 'nn_ref_in_mode_transport' AS dictionary_name, 'Mode of transport' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Referred = Yes' AS condition_text
    UNION ALL
    SELECT 'admitted_from' AS rule_id, 'nn_ref_in_admitted_from' AS dictionary_name, 'Admitted from' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Referred = Yes' AS condition_text
    UNION ALL
    SELECT 'apgar_score_1_min' AS rule_id, 'nn_birth_assess_apgar1' AS dictionary_name, 'Apgar score at 1 minute' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Cried after birth = No' AS condition_text
    UNION ALL
    SELECT 'apgar_score_5_min' AS rule_id, 'nn_birth_assess_apgar5' AS dictionary_name, 'Apgar score at 5 minutes' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Cried after birth = No' AS condition_text
    UNION ALL
    SELECT 'apgar_score_10_min' AS rule_id, 'nn_birth_assess_apgar10' AS dictionary_name, 'Apgar score at 10 minutes' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Cried after birth = No' AS condition_text
    UNION ALL
    SELECT 'resuscitation_method' AS rule_id, 'nn_birth_assess_resuscitation_methods' AS dictionary_name, 'Was resuscitation needed at birth?' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Shown unless Place of birth = Home and Cried after birth = Yes' AS condition_text
    UNION ALL
    SELECT 'steroids_given' AS rule_id, 'nn_preg_hist_steroids_given' AS dictionary_name, 'Were steroids given?' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Gestation in weeks > 0 and < 37' AS condition_text
    UNION ALL
    SELECT 'ultrasound_scanning' AS rule_id, 'nn_preg_hist_ultra_sound_scanning' AS dictionary_name, 'Ultra sound scanning - USS' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Gestation method assessment = Ultra Sound Scanning (USS)' AS condition_text
    UNION ALL
    SELECT 'duration_rupture_membranes' AS rule_id, 'nn_preg_hist_duration_rupture_membranes' AS dictionary_name, 'Duration of rupture of membranes' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Rupture of membranes = Yes' AS condition_text
    UNION ALL
    SELECT 'analgesia_drug' AS rule_id, 'nn_preg_hist_analgesias_drug' AS dictionary_name, 'Analgesia drug' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Maternal analgesia = Yes' AS condition_text
    UNION ALL
    SELECT 'do_hiv_retest' AS rule_id, 'nn_mother_hiv_retest' AS dictionary_name, 'Do a HIV re-test?' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Mother HIV status <> Reactive' AS condition_text
    UNION ALL
    SELECT 'baby_given_nvp' AS rule_id, 'nn_mother_baby_given_nvp' AS dictionary_name, 'Was baby given NVP?' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Mother HIV status = Reactive' AS condition_text
    UNION ALL
    SELECT 'mother_treated_vdrl' AS rule_id, 'nn_mother_mother_treated_vdrl' AS dictionary_name, 'Was the mother treated for VDRL/Syphilis?' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Mother VDRL result <> Negative' AS condition_text
    UNION ALL
    SELECT 'three_doses_completed' AS rule_id, 'nn_mother_all_three_doses_completed' AS dictionary_name, 'Were all 3 doses completed?' AS label, 'Enrollment' AS section, 'CONDITIONAL' AS requirement, 'Mother treated for VDRL = Yes' AS condition_text
    UNION ALL
    SELECT 'tactile_trunk_temperature' AS rule_id, 'nn_triage_trunk_temperature_status' AS dictionary_name, 'Does the trunk feel cold or warm?' AS label, 'Triage' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'baby_breathing_status' AS rule_id, 'nn_triage_breathing' AS dictionary_name, 'Is the baby breathing?' AS label, 'Triage' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'airway_status' AS rule_id, 'nn_triage_airway_status' AS dictionary_name, 'Airway' AS label, 'Triage' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'respiratory_rate' AS rule_id, 'nn_triage_respiratory_rate' AS dictionary_name, 'Respiratory rate' AS label, 'Triage' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'warm_peripherals' AS rule_id, 'nn_triage_warm_peripherals' AS dictionary_name, 'Does the baby have warm peripherals?' AS label, 'Triage' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'pulse_volume' AS rule_id, 'nn_triage_pulse_volume_primary' AS dictionary_name, 'Pulse volume' AS label, 'Triage' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'avpu' AS rule_id, 'nn_triage_avpu_primary' AS dictionary_name, 'AVPU' AS label, 'Triage' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'convulsions_or_twitching' AS rule_id, 'nn_triage_convulsions_primary' AS dictionary_name, 'Convulsions, seizures or twitching?' AS label, 'Triage' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'signs_of_dehydration' AS rule_id, 'nn_triage_dehydration_signs' AS dictionary_name, 'Signs of dehydration' AS label, 'Triage' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
    SELECT 'pulse' AS rule_id, 'nn_triage_heart_rate' AS dictionary_name, 'Heart rate (bpm)' AS label, 'Triage' AS section, 'MANDATORY' AS requirement, '' AS condition_text
    UNION ALL
