),

baby_rule_results AS (
    -- baby_level is read once: every rule result is packed as [applicable, present] in one JSON object per baby
    SELECT person_id, JSON_OBJECT(
        'mother_identifier', JSON_ARRAY(1, CASE WHEN (mother_identifier) IS NOT NULL THEN 1 ELSE 0 END),
        'multiple_birth_type', JSON_ARRAY(1, CASE WHEN (multiple_birth_type) IS NOT NULL THEN 1 ELSE 0 END),
        'place_of_birth', JSON_ARRAY(1, CASE WHEN (place_of_birth) IS NOT NULL THEN 1 ELSE 0 END),
        'multiple_birth', JSON_ARRAY(1, CASE WHEN (multiple_birth) IS NOT NULL THEN 1 ELSE 0 END),
        'birthdate', JSON_ARRAY(1, CASE WHEN (birthdate) IS NOT NULL THEN 1 ELSE 0 END),
        'type_of_birth', JSON_ARRAY(1, CASE WHEN (COALESCE(type_of_birth, time_of_delivery)) IS NOT NULL THEN 1 ELSE 0 END),
        'referred', JSON_ARRAY(1, CASE WHEN (referred) IS NOT NULL THEN 1 ELSE 0 END),
        'cried_after_birth', JSON_ARRAY(1, CASE WHEN (COALESCE(cried_after_birth, cried_at_birth)) IS NOT NULL THEN 1 ELSE 0 END),
        'gestation_in_weeks', JSON_ARRAY(1, CASE WHEN (gestation_in_weeks) IS NOT NULL THEN 1 ELSE 0 END),
        'gestation_method_assessment', JSON_ARRAY(1, CASE WHEN (gestation_method_assessment) IS NOT NULL THEN 1 ELSE 0 END),
        'onset_of_labor', JSON_ARRAY(1, CASE WHEN (onset_of_labor) IS NOT NULL THEN 1 ELSE 0 END),
        'rupture_of_membranes', JSON_ARRAY(1, CASE WHEN (rupture_of_membranes) IS NOT NULL THEN 1 ELSE 0 END),
        'offensive_liquor', JSON_ARRAY(1, CASE WHEN (offensive_liquor) IS NOT NULL THEN 1 ELSE 0 END),
        'mode_of_delivery', JSON_ARRAY(1, CASE WHEN (mode_of_delivery) IS NOT NULL THEN 1 ELSE 0 END),
        'meconium_present', JSON_ARRAY(1, CASE WHEN (meconium_present) IS NOT NULL THEN 1 ELSE 0 END),
        'maternal_analgesia', JSON_ARRAY(1, CASE WHEN (maternal_analgesia) IS NOT NULL THEN 1 ELSE 0 END),
        'anesthesia_used', JSON_ARRAY(1, CASE WHEN (anesthesia_used) IS NOT NULL THEN 1 ELSE 0 END),
        'teo', JSON_ARRAY(1, CASE WHEN (teo) IS NOT NULL THEN 1 ELSE 0 END),
        'chlorohexidine_cord_care', JSON_ARRAY(1, CASE WHEN (chlorohexidine_cord_care) IS NOT NULL THEN 1 ELSE 0 END),
        'vitamin_k_given', JSON_ARRAY(1, CASE WHEN (vitamin_k_given) IS NOT NULL THEN 1 ELSE 0 END),
        'mother_status', JSON_ARRAY(1, CASE WHEN (mother_status) IS NOT NULL THEN 1 ELSE 0 END),
        'mother_hiv_status', JSON_ARRAY(1, CASE WHEN (COALESCE(mother_hiv_status, hiv_status)) IS NOT NULL THEN 1 ELSE 0 END),
        'last_hiv_test_date', JSON_ARRAY(1, CASE WHEN (last_hiv_test_date) IS NOT NULL THEN 1 ELSE 0 END),
        'mother_vdrl_result', JSON_ARRAY(1, CASE WHEN (mother_vdrl_result) IS NOT NULL THEN 1 ELSE 0 END),
        'baby_tested_hepatitis', JSON_ARRAY(1, CASE WHEN (baby_tested_hepatitis) IS NOT NULL THEN 1 ELSE 0 END),
        'known_medical_condition', JSON_ARRAY(1, CASE WHEN (known_medical_condition) IS NOT NULL THEN 1 ELSE 0 END),
        'tetanus_diphtheria', JSON_ARRAY(1, CASE WHEN (tetanus_diphtheria) IS NOT NULL THEN 1 ELSE 0 END),
        'birth_facility_name', JSON_ARRAY(CASE WHEN COALESCE(((LOWER(place_of_birth) LIKE '%hospital%' OR LOWER(place_of_birth) LIKE '%health%') AND LOWER(referred) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (birth_facility_name) IS NOT NULL THEN 1 ELSE 0 END),
        'referred_from', JSON_ARRAY(CASE WHEN COALESCE((LOWER(referred) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (referred_from) IS NOT NULL THEN 1 ELSE 0 END),
        'referring_facility_name', JSON_ARRAY(CASE WHEN COALESCE((LOWER(referred) = 'yes' AND LOWER(referred_from) <> 'other'), 0) THEN 1 ELSE 0 END, CASE WHEN (COALESCE(referring_facility_name, referral_facility)) IS NOT NULL THEN 1 ELSE 0 END),
        'mode_of_transport', JSON_ARRAY(CASE WHEN COALESCE((LOWER(referred) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (mode_of_transport) IS NOT NULL THEN 1 ELSE 0 END),
        'admitted_from', JSON_ARRAY(CASE WHEN COALESCE((LOWER(referred) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (admitted_from) IS NOT NULL THEN 1 ELSE 0 END),
        'apgar_score_1_min', JSON_ARRAY(CASE WHEN COALESCE((LOWER(COALESCE(cried_after_birth, cried_at_birth)) = 'no'), 0) THEN 1 ELSE 0 END, CASE WHEN (apgar_score_1_min) IS NOT NULL THEN 1 ELSE 0 END),
        'apgar_score_5_min', JSON_ARRAY(CASE WHEN COALESCE((LOWER(COALESCE(cried_after_birth, cried_at_birth)) = 'no'), 0) THEN 1 ELSE 0 END, CASE WHEN (apgar_score_5_min) IS NOT NULL THEN 1 ELSE 0 END),
        'apgar_score_10_min', JSON_ARRAY(CASE WHEN COALESCE((LOWER(COALESCE(cried_after_birth, cried_at_birth)) = 'no'), 0) THEN 1 ELSE 0 END, CASE WHEN (apgar_score_10_min) IS NOT NULL THEN 1 ELSE 0 END),
        'resuscitation_method', JSON_ARRAY(CASE WHEN COALESCE((NOT (LOWER(place_of_birth) = 'home' AND LOWER(COALESCE(cried_after_birth, cried_at_birth)) = 'yes')), 0) THEN 1 ELSE 0 END, CASE WHEN (resuscitation_method) IS NOT NULL THEN 1 ELSE 0 END),
        'steroids_given', JSON_ARRAY(CASE WHEN COALESCE((CAST(gestation_in_weeks AS DECIMAL(5,1)) > 0 AND CAST(gestation_in_weeks AS DECIMAL(5,1)) < 37), 0) THEN 1 ELSE 0 END, CASE WHEN (steroids_given) IS NOT NULL THEN 1 ELSE 0 END),
        'ultrasound_scanning', JSON_ARRAY(CASE WHEN COALESCE((LOWER(gestation_method_assessment) LIKE '%ultra%'), 0) THEN 1 ELSE 0 END, CASE WHEN (ultrasound_scanning) IS NOT NULL THEN 1 ELSE 0 END),
        'duration_rupture_membranes', JSON_ARRAY(CASE WHEN COALESCE((LOWER(rupture_of_membranes) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (duration_rupture_membranes) IS NOT NULL THEN 1 ELSE 0 END),
        'analgesia_drug', JSON_ARRAY(CASE WHEN COALESCE((LOWER(maternal_analgesia) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (analgesia_drug) IS NOT NULL THEN 1 ELSE 0 END),
        'do_hiv_retest', JSON_ARRAY(CASE WHEN COALESCE((LOWER(COALESCE(mother_hiv_status, hiv_status)) <> 'reactive'), 0) THEN 1 ELSE 0 END, CASE WHEN (do_hiv_retest) IS NOT NULL THEN 1 ELSE 0 END),
        'baby_given_nvp', JSON_ARRAY(CASE WHEN COALESCE((LOWER(COALESCE(mother_hiv_status, hiv_status)) = 'reactive'), 0) THEN 1 ELSE 0 END, CASE WHEN (baby_given_nvp) IS NOT NULL THEN 1 ELSE 0 END),
        'mother_treated_vdrl', JSON_ARRAY(CASE WHEN COALESCE((LOWER(mother_vdrl_result) <> 'negative'), 0) THEN 1 ELSE 0 END, CASE WHEN (mother_treated_vdrl) IS NOT NULL THEN 1 ELSE 0 END),
        'three_doses_completed', JSON_ARRAY(CASE WHEN COALESCE((LOWER(mother_treated_vdrl) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (three_doses_completed) IS NOT NULL THEN 1 ELSE 0 END),
        'tactile_trunk_temperature', JSON_ARRAY(1, CASE WHEN (tactile_trunk_temperature) IS NOT NULL THEN 1 ELSE 0 END),
        'baby_breathing_status', JSON_ARRAY(1, CASE WHEN (baby_breathing_status) IS NOT NULL THEN 1 ELSE 0 END),
        'airway_status', JSON_ARRAY(1, CASE WHEN (airway_status) IS NOT NULL THEN 1 ELSE 0 END),
        'respiratory_rate', JSON_ARRAY(1, CASE WHEN (respiratory_rate) IS NOT NULL THEN 1 ELSE 0 END),
        'warm_peripherals', JSON_ARRAY(1, CASE WHEN (warm_peripherals) IS NOT NULL THEN 1 ELSE 0 END),
        'pulse_volume', JSON_ARRAY(1, CASE WHEN (pulse_volume) IS NOT NULL THEN 1 ELSE 0 END),
        'avpu', JSON_ARRAY(1, CASE WHEN (avpu) IS NOT NULL THEN 1 ELSE 0 END),
        'convulsions_or_twitching', JSON_ARRAY(1, CASE WHEN (convulsions_or_twitching) IS NOT NULL THEN 1 ELSE 0 END),
        'signs_of_dehydration', JSON_ARRAY(1, CASE WHEN (signs_of_dehydration) IS NOT NULL THEN 1 ELSE 0 END),
        'pulse', JSON_ARRAY(1, CASE WHEN (pulse) IS NOT NULL THEN 1 ELSE 0 END),
        'oxygen_available_at_facility', JSON_ARRAY(1, CASE WHEN (oxygen_available_at_facility) IS NOT NULL THEN 1 ELSE 0 END),
        'current_weight', JSON_ARRAY(1, CASE WHEN (COALESCE(current_weight, weight_grams, weight)) IS NOT NULL THEN 1 ELSE 0 END),
        'birth_weight', JSON_ARRAY(1, CASE WHEN (birth_weight) IS NOT NULL THEN 1 ELSE 0 END),
        'gender', JSON_ARRAY(1, CASE WHEN (gender) IS NOT NULL THEN 1 ELSE 0 END),
        'breathing_triage', JSON_ARRAY(CASE WHEN COALESCE((LOWER(baby_breathing_status) = 'no' OR LOWER(airway_status) = 'blocked'), 0) THEN 1 ELSE 0 END, CASE WHEN (breathing_triage) IS NOT NULL THEN 1 ELSE 0 END),
        'central_capillary_refill_time', JSON_ARRAY(CASE WHEN COALESCE((LOWER(warm_peripherals) = 'no'), 0) THEN 1 ELSE 0 END, CASE WHEN (central_capillary_refill_time) IS NOT NULL THEN 1 ELSE 0 END),
        'baby_dehydrated', JSON_ARRAY(CASE WHEN COALESCE((signs_of_dehydration IS NOT NULL AND LOWER(signs_of_dehydration) <> 'none'), 0) THEN 1 ELSE 0 END, CASE WHEN (baby_dehydrated) IS NOT NULL THEN 1 ELSE 0 END),
        'temperature', JSON_ARRAY(CASE WHEN COALESCE((LOWER(can_measure_temperature) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (temperature) IS NOT NULL THEN 1 ELSE 0 END),
        'oxygen_saturation', JSON_ARRAY(CASE WHEN COALESCE((LOWER(can_measure_oxygen_saturation) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (oxygen_saturation) IS NOT NULL THEN 1 ELSE 0 END),
        'oxygen_unavailable_reason', JSON_ARRAY(CASE WHEN COALESCE((LOWER(oxygen_available_at_facility) = 'no'), 0) THEN 1 ELSE 0 END, CASE WHEN (oxygen_unavailable_reason) IS NOT NULL THEN 1 ELSE 0 END),
        'oxygen_saturation_on_oxygen', JSON_ARRAY(CASE WHEN COALESCE((LOWER(can_measure_oxygen_saturation) = 'yes' AND LOWER(oxygen_available_at_facility) = 'yes' AND (CAST(oxygen_saturation AS DECIMAL(6,2)) < 90 OR CAST(respiratory_rate AS DECIMAL(6,2)) > 80)), 0) THEN 1 ELSE 0 END, CASE WHEN (oxygen_saturation_on_oxygen) IS NOT NULL THEN 1 ELSE 0 END),
        'baby_symptomatic_low_blood_sugar', JSON_ARRAY(CASE WHEN COALESCE(((LOWER(blood_sugar_unit) LIKE 'mg%' AND CAST(blood_sugar AS DECIMAL(6,2)) < 45) OR (LOWER(blood_sugar_unit) LIKE 'mmol%' AND CAST(blood_sugar AS DECIMAL(6,2)) < 2.5)), 0) THEN 1 ELSE 0 END, CASE WHEN (baby_symptomatic_low_blood_sugar) IS NOT NULL THEN 1 ELSE 0 END),
        'readmission', JSON_ARRAY(1, CASE WHEN (readmission) IS NOT NULL THEN 1 ELSE 0 END),
        'presenting_complaint', JSON_ARRAY(1, CASE WHEN (presenting_complaint) IS NOT NULL THEN 1 ELSE 0 END),
        'activity', JSON_ARRAY(1, CASE WHEN (activity) IS NOT NULL THEN 1 ELSE 0 END),
        'head_circumference', JSON_ARRAY(1, CASE WHEN (COALESCE(head_circumference, circumference_cm)) IS NOT NULL THEN 1 ELSE 0 END),
        'fontanelle', JSON_ARRAY(1, CASE WHEN (fontanelle) IS NOT NULL THEN 1 ELSE 0 END),
        'head', JSON_ARRAY(1, CASE WHEN (head) IS NOT NULL THEN 1 ELSE 0 END),
        'colour', JSON_ARRAY(1, CASE WHEN (colour) IS NOT NULL THEN 1 ELSE 0 END),
        'central_cyanosis', JSON_ARRAY(1, CASE WHEN (central_cyanosis) IS NOT NULL THEN 1 ELSE 0 END),
        'palate', JSON_ARRAY(1, CASE WHEN (palate) IS NOT NULL THEN 1 ELSE 0 END),
        'capillary_refill_time', JSON_ARRAY(1, CASE WHEN (COALESCE(capillary_refill_time, crt_less_than_3_seconds, crt_3_or_more_seconds)) IS NOT NULL THEN 1 ELSE 0 END),
        'femoral_pulses', JSON_ARRAY(1, CASE WHEN (COALESCE(femoral_pulses, femoral_pulse_palpable)) IS NOT NULL THEN 1 ELSE 0 END),
        'genitalia', JSON_ARRAY(1, CASE WHEN (genitalia) IS NOT NULL THEN 1 ELSE 0 END),
        'anus_assessment', JSON_ARRAY(1, CASE WHEN (anus_assessment) IS NOT NULL THEN 1 ELSE 0 END),
        'congenital_abnormality', JSON_ARRAY(1, CASE WHEN (congenital_abnormality) IS NOT NULL THEN 1 ELSE 0 END),
        'baby_feeding', JSON_ARRAY(1, CASE WHEN (baby_feeding) IS NOT NULL THEN 1 ELSE 0 END),
        'is_baby_vomiting', JSON_ARRAY(1, CASE WHEN (is_baby_vomiting) IS NOT NULL THEN 1 ELSE 0 END),
        'passage_of_meconium', JSON_ARRAY(1, CASE WHEN (passage_of_meconium) IS NOT NULL THEN 1 ELSE 0 END),
        'frequency_of_stooling', JSON_ARRAY(1, CASE WHEN (frequency_of_stooling) IS NOT NULL THEN 1 ELSE 0 END),
        'color_of_stools', JSON_ARRAY(1, CASE WHEN (color_of_stools) IS NOT NULL THEN 1 ELSE 0 END),
        'consistency_of_stools', JSON_ARRAY(1, CASE WHEN (consistency_of_stools) IS NOT NULL THEN 1 ELSE 0 END),
        'baby_catheterized', JSON_ARRAY(1, CASE WHEN (baby_catheterized) IS NOT NULL THEN 1 ELSE 0 END),
        'baby_passing_urine', JSON_ARRAY(1, CASE WHEN (baby_passing_urine) IS NOT NULL THEN 1 ELSE 0 END),
        'weight_trend_since_birth', JSON_ARRAY(1, CASE WHEN (weight_trend_since_birth) IS NOT NULL THEN 1 ELSE 0 END),
        'baby_oral_thrush', JSON_ARRAY(1, CASE WHEN (baby_oral_thrush) IS NOT NULL THEN 1 ELSE 0 END),
        'baby_oral_sores', JSON_ARRAY(1, CASE WHEN (baby_oral_sores) IS NOT NULL THEN 1 ELSE 0 END),
        'baby_tongue_tie', JSON_ARRAY(1, CASE WHEN (baby_tongue_tie) IS NOT NULL THEN 1 ELSE 0 END),
        'abdominal_distension', JSON_ARRAY(1, CASE WHEN (abdominal_distension) IS NOT NULL THEN 1 ELSE 0 END),
        'umbilical_condition', JSON_ARRAY(1, CASE WHEN (umbilical_condition) IS NOT NULL THEN 1 ELSE 0 END),
        'skin_rash', JSON_ARRAY(1, CASE WHEN (skin_rash) IS NOT NULL THEN 1 ELSE 0 END),
        'talipes', JSON_ARRAY(1, CASE WHEN (talipes) IS NOT NULL THEN 1 ELSE 0 END),
        'extra_digits', JSON_ARRAY(1, CASE WHEN (extra_digits) IS NOT NULL THEN 1 ELSE 0 END),
        'spinal_bifida', JSON_ARRAY(1, CASE WHEN (spinal_bifida) IS NOT NULL THEN 1 ELSE 0 END),
        'type_of_feed', JSON_ARRAY(CASE WHEN COALESCE((LOWER(baby_feeding) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (type_of_feed) IS NOT NULL THEN 1 ELSE 0 END),
        'mode_of_feeding', JSON_ARRAY(CASE WHEN COALESCE((LOWER(baby_feeding) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (mode_of_feeding) IS NOT NULL THEN 1 ELSE 0 END),
        'frequency_of_feeding', JSON_ARRAY(CASE WHEN COALESCE((LOWER(baby_feeding) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (frequency_of_feeding) IS NOT NULL THEN 1 ELSE 0 END),
        'duration_of_feeding', JSON_ARRAY(CASE WHEN COALESCE((LOWER(baby_feeding) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (duration_of_feeding) IS NOT NULL THEN 1 ELSE 0 END),
        'effort_during_feeding', JSON_ARRAY(CASE WHEN COALESCE((LOWER(baby_feeding) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (effort_during_feeding) IS NOT NULL THEN 1 ELSE 0 END),
        'blood_in_stools', JSON_ARRAY(CASE WHEN COALESCE((LOWER(color_of_stools) <> 'none' AND LOWER(consistency_of_stools) <> 'none'), 0) THEN 1 ELSE 0 END, CASE WHEN (blood_in_stools) IS NOT NULL THEN 1 ELSE 0 END),
        'mucus_in_stools', JSON_ARRAY(CASE WHEN COALESCE((LOWER(color_of_stools) <> 'none' AND LOWER(consistency_of_stools) <> 'none'), 0) THEN 1 ELSE 0 END, CASE WHEN (mucus_in_stools) IS NOT NULL THEN 1 ELSE 0 END),
        'wet_nappies_per_day', JSON_ARRAY(CASE WHEN COALESCE((LOWER(baby_passing_urine) = 'yes' AND LOWER(baby_catheterized) = 'no'), 0) THEN 1 ELSE 0 END, CASE WHEN (wet_nappies_per_day) IS NOT NULL THEN 1 ELSE 0 END),
        'color_of_urine', JSON_ARRAY(CASE WHEN COALESCE((LOWER(baby_passing_urine) = 'yes' AND LOWER(baby_catheterized) = 'no'), 0) THEN 1 ELSE 0 END, CASE WHEN (color_of_urine) IS NOT NULL THEN 1 ELSE 0 END),
        'respiratory_distress', JSON_ARRAY(1, CASE WHEN (respiratory_distress) IS NOT NULL THEN 1 ELSE 0 END),
        'stethoscope_available', JSON_ARRAY(1, CASE WHEN (stethoscope_available) IS NOT NULL THEN 1 ELSE 0 END),
        'abdomen_soft_normal', JSON_ARRAY(1, CASE WHEN (abdomen_soft_normal) IS NOT NULL THEN 1 ELSE 0 END),
        'umbilicus_healthy', JSON_ARRAY(1, CASE WHEN (umbilicus_healthy) IS NOT NULL THEN 1 ELSE 0 END),
        'abdomen_distended_veins', JSON_ARRAY(1, CASE WHEN (abdomen_distended_veins) IS NOT NULL THEN 1 ELSE 0 END),
        'abdomen_tender', JSON_ARRAY(1, CASE WHEN (abdomen_tender) IS NOT NULL THEN 1 ELSE 0 END),
        'abdomen_shiny', JSON_ARRAY(1, CASE WHEN (abdomen_shiny) IS NOT NULL THEN 1 ELSE 0 END),
        'abdomen_color_change', JSON_ARRAY(1, CASE WHEN (abdomen_color_change) IS NOT NULL THEN 1 ELSE 0 END),
        'hepatomegaly', JSON_ARRAY(1, CASE WHEN (hepatomegaly) IS NOT NULL THEN 1 ELSE 0 END),
        'splenomegaly', JSON_ARRAY(1, CASE WHEN (splenomegaly) IS NOT NULL THEN 1 ELSE 0 END),
        'palpable_kidneys', JSON_ARRAY(1, CASE WHEN (palpable_kidneys) IS NOT NULL THEN 1 ELSE 0 END),
        'tone_assessment', JSON_ARRAY(1, CASE WHEN (tone_assessment) IS NOT NULL THEN 1 ELSE 0 END),
        'suck_reflex', JSON_ARRAY(1, CASE WHEN (suck_reflex) IS NOT NULL THEN 1 ELSE 0 END),
        'grasp_reflex', JSON_ARRAY(1, CASE WHEN (grasp_reflex) IS NOT NULL THEN 1 ELSE 0 END),
        'moro_reflex', JSON_ARRAY(1, CASE WHEN (moro_reflex) IS NOT NULL THEN 1 ELSE 0 END),
        'musculoskeletal_deformities', JSON_ARRAY(1, CASE WHEN (musculoskeletal_deformities) IS NOT NULL THEN 1 ELSE 0 END),
        'skin_findings', JSON_ARRAY(1, CASE WHEN (skin_findings) IS NOT NULL THEN 1 ELSE 0 END),
        'birth_asphyxia_suspected', JSON_ARRAY(1, CASE WHEN (birth_asphyxia_suspected) IS NOT NULL THEN 1 ELSE 0 END),
        'respiratory_distress_signs', JSON_ARRAY(CASE WHEN COALESCE((LOWER(respiratory_distress) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (COALESCE(nasal_flaring, fast_breathing, severe_respiratory_distress)) IS NOT NULL THEN 1 ELSE 0 END),
        'chest_clear', JSON_ARRAY(CASE WHEN COALESCE((LOWER(stethoscope_available) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (chest_clear) IS NOT NULL THEN 1 ELSE 0 END),
        'normal_heart_sounds', JSON_ARRAY(CASE WHEN COALESCE((LOWER(stethoscope_available) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (normal_heart_sounds) IS NOT NULL THEN 1 ELSE 0 END),
        'thompson_respiration_score', JSON_ARRAY(CASE WHEN COALESCE((LOWER(birth_asphyxia_suspected) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (thompson_respiration_score) IS NOT NULL THEN 1 ELSE 0 END),
        'thompson_suck_score', JSON_ARRAY(CASE WHEN COALESCE((LOWER(birth_asphyxia_suspected) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (thompson_suck_score) IS NOT NULL THEN 1 ELSE 0 END),
        'thompson_moro_score', JSON_ARRAY(CASE WHEN COALESCE((LOWER(birth_asphyxia_suspected) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (thompson_moro_score) IS NOT NULL THEN 1 ELSE 0 END),
        'thompson_grasp_score', JSON_ARRAY(CASE WHEN COALESCE((LOWER(birth_asphyxia_suspected) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (thompson_grasp_score) IS NOT NULL THEN 1 ELSE 0 END),
        'thompson_fontanelle_score', JSON_ARRAY(CASE WHEN COALESCE((LOWER(birth_asphyxia_suspected) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (thompson_fontanelle_score) IS NOT NULL THEN 1 ELSE 0 END),
        'thompson_tone_score', JSON_ARRAY(CASE WHEN COALESCE((LOWER(birth_asphyxia_suspected) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (thompson_tone_score) IS NOT NULL THEN 1 ELSE 0 END),
        'thompson_consciousness_score', JSON_ARRAY(CASE WHEN COALESCE((LOWER(birth_asphyxia_suspected) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (thompson_consciousness_score) IS NOT NULL THEN 1 ELSE 0 END),
        'thompson_fits_score', JSON_ARRAY(CASE WHEN COALESCE((LOWER(birth_asphyxia_suspected) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (thompson_fits_score) IS NOT NULL THEN 1 ELSE 0 END),
        'thompson_posture_score', JSON_ARRAY(CASE WHEN COALESCE((LOWER(birth_asphyxia_suspected) = 'yes'), 0) THEN 1 ELSE 0 END, CASE WHEN (thompson_posture_score) IS NOT NULL THEN 1 ELSE 0 END),
        'primary_diagnosis', JSON_ARRAY(1, CASE WHEN (primary_diagnosis) IS NOT NULL THEN 1 ELSE 0 END),
        'treatment', JSON_ARRAY(1, CASE WHEN (treatment) IS NOT NULL THEN 1 ELSE 0 END),
        'thermal_care', JSON_ARRAY(CASE WHEN COALESCE((LOWER(treatment) LIKE '%thermal%'), 0) THEN 1 ELSE 0 END, CASE WHEN (thermal_care) IS NOT NULL THEN 1 ELSE 0 END),
        'oxygen_therapy', JSON_ARRAY(CASE WHEN COALESCE((LOWER(treatment) LIKE '%oxygen%'), 0) THEN 1 ELSE 0 END, CASE WHEN (oxygen_therapy) IS NOT NULL THEN 1 ELSE 0 END),
        'feeding_support', JSON_ARRAY(CASE WHEN COALESCE((LOWER(treatment) LIKE '%feeding%'), 0) THEN 1 ELSE 0 END, CASE WHEN (feeding_support) IS NOT NULL THEN 1 ELSE 0 END),
        'clinical_review_outcome', JSON_ARRAY(1, CASE WHEN (clinical_review_outcome) IS NOT NULL THEN 1 ELSE 0 END),
        'clinical_review_signoff', JSON_ARRAY(1, CASE WHEN (CASE WHEN clinician_notes LIKE '%NEONATAL_SIGNOFF%' THEN clinician_notes END) IS NOT NULL THEN 1 ELSE 0 END)
    ) AS j
    FROM baby_level
),

field_status AS (
    -- Unpivot the JSON into one row per baby per rule
    SELECT
        b.person_id,
        k.rule_id,
        r.requirement,
        CAST(JSON_EXTRACT(b.j, CONCAT('$.', k.rule_id, '[0]')) AS UNSIGNED) AS applicable,
        CAST(JSON_EXTRACT(b.j, CONCAT('$.', k.rule_id, '[1]')) AS UNSIGNED) AS present
    FROM baby_rule_results b
    JOIN JSON_TABLE(JSON_KEYS(b.j), '$[*]' COLUMNS (rule_id VARCHAR(100) PATH '$')) k
    INNER JOIN rules r ON r.rule_id = k.rule_id
),

baby_dq AS (
    -- Per-baby counts of mandatory and conditional fields
    SELECT
        b.person_id,
        SUM(CASE WHEN f.requirement = 'MANDATORY' THEN 1 ELSE 0 END) AS mandatory_fields,
        SUM(CASE WHEN f.requirement = 'MANDATORY' AND f.present = 1 THEN 1 ELSE 0 END) AS mandatory_present,
        SUM(CASE WHEN f.requirement = 'MANDATORY' AND f.present = 0 THEN 1 ELSE 0 END) AS mandatory_missing,
        SUM(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 THEN 1 ELSE 0 END) AS conditional_required,
        SUM(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 AND f.present = 1 THEN 1 ELSE 0 END) AS conditional_present,
        SUM(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 AND f.present = 0 THEN 1 ELSE 0 END) AS conditional_missing,
        GROUP_CONCAT(CASE WHEN f.requirement = 'MANDATORY' AND f.present = 0 THEN f.rule_id END ORDER BY f.rule_id SEPARATOR '; ') AS missing_mandatory_fields,
        GROUP_CONCAT(CASE WHEN f.requirement = 'CONDITIONAL' AND f.applicable = 1 AND f.present = 0 THEN f.rule_id END ORDER BY f.rule_id SEPARATOR '; ') AS missing_conditional_fields
    FROM baby_level b
    INNER JOIN field_status f ON f.person_id = b.person_id
    GROUP BY b.person_id
)

SELECT
    b.person_id, b.location_id, b.first_visit_date, b.last_visit_date, b.number_of_visits,
    d.mandatory_fields, d.mandatory_present, d.mandatory_missing,
    ROUND(100 * d.mandatory_present / d.mandatory_fields, 1) AS pct_mandatory_present,
    d.conditional_required, d.conditional_present, d.conditional_missing,
    CASE WHEN d.mandatory_missing = 0 THEN 'YES' ELSE 'NO' END AS all_mandatory_present,
    d.missing_mandatory_fields,
    d.missing_conditional_fields
FROM baby_level b
INNER JOIN baby_dq d ON d.person_id = b.person_id
ORDER BY d.mandatory_missing DESC, b.person_id;
